import { channel } from 'node:diagnostics_channel';
import { appendFileSync } from 'node:fs';

const target = new URL('./passive-refusals.jsonl', import.meta.url);
let observed = 0;
let written = 0;
let oversize = 0;
let writeFailures = 0;
channel('agent-teams.legacy-host.first-refusal').subscribe(value => {
  try {
    observed++;
    if (observed > 8) return;
    const text = JSON.stringify({ event: observed, pid: process.pid, value });
    if (Buffer.byteLength(text) > 16 * 1024) { oversize++; return; }
    appendFileSync(target, text + '\n');
    written++;
  } catch { writeFailures++; }
});
process.once('exit', () => {
  try {
    appendFileSync(new URL('./passive-refusals-exit.jsonl', import.meta.url),
      JSON.stringify({ pid: process.pid, observed, written, oversize, writeFailures }) + '\n');
  } catch { /* Observer failure cannot change the original result. */ }
});
